new Vue({el:"#app",data:{posts:[],newPost:{title:"",content:""}},mounted(){this.fetchPosts()},methods:{fetchPosts(){fetch("/api.php").then((t=>t.json())).then((t=>{this.posts=t})).catch((t=>console.error("Error fetching posts:",t)))},createPost(){const t={title:this.newPost.title,content:this.newPost.content};fetch("/api.php",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(t)}).then((t=>t.json())).then((t=>{t.message?(alert(t.message),this.newPost.title="",this.newPost.content="",this.fetchPosts()):alert(t.error||"Error occurred")})).catch((t=>console.error("Error creating post:",t)))}}});